    const w=C.createWorkOrder({id,name:id,productName:base.productName,materialId:base.materialId,gtin:base.gtin,batch,quantity:12000+(i%6)*1000,manufacturingDate:"2026-10-01",expiryDate:"2029-09-30",sourceGln:base.sourceGln,site:base.site,line:base.line,recipeId:base.recipeId,recipeVersion:base.recipeVersion,serializationMachineId:base.serializationMachineId,aggregationMachineId:base.aggregationMachineId,storage:base.storage});
