function createMaintenanceModal(){openModal("Create maintenance request",`<div class="notice info"><strong>Manual repair ticket</strong>Link the request to a machine, Work Order, and optional source alarm.</div><div style="height:14px"></div><div class="fields"><div class="field full"><label>Title</label><input id="mrTitle" value="Inspect machine or sensor"></div><div class="field"><label>Asset / machine</label><select id="mrAsset">${db.machines.map(m=>`<option>${esc(m.id)} · ${esc(m.name)}</option>`).join("")}</select></div><div class="field"><label>Priority</label><select id="mrPriority"><option>critical</option><option selected>high</option><option>warning</option></select></div><div class="field"><label>Work Order</label><select id="mrWo">${db.workOrders.slice(0,20).map(w=>`<option value="${esc(w.id)}">${esc(w.id)} · Batch ${esc(w.batch)}</option>`).join("")}</select></div><div class="field"><label>Owner</label><input id="mrOwner" value="Maintenance team"></div><div class="field full"><label>Description</label><textarea id="mrDescription">Describe the fault, checks, and expected repair.</textarea></div></div>`,`Create request`,()=>{const r={id:`MR-${1000+db.maintenanceRequests.length+1}`,title:$("#mrTitle").value||"Maintenance investigation",asset:$("#mrAsset").value,priority:$("#mrPriority").value,status:"open",owner:$("#mrOwner").value||"Maintenance team",source:"Manual",workOrderId:$("#mrWo").value,createdAt:"Just now",description:$("#mrDescription").value};db.maintenanceRequests.unshift(r);modalState=null;render("maintenance");notify(`${r.id} created.`)})}
const alarmAutomationHandle=handle;handle=(action,el)=>{if(action==="newMaintenance")return createMaintenanceModal();if(action==="simulateAlert"){const a=db.alerts.find(x=>x.id===el.dataset.alert);if(!a)return;a.occurrences=(a.occurrences||0)+1;a.lastTriggered="Just now";let created=null;if(a.occurrences>=(a.repeatCount||5)){created=createMaintenanceFromAlert(a);a.status="triggered";if(a.actions?.includes("hold")){const affected=db.workOrders.find(x=>x.id===a.workOrderId);if(affected)affected.status="on_hold"}}render("alarms");return notify(created?`${a.id} triggered · ${created.id} created automatically.`:`Occurrence recorded: ${a.occurrences}/${a.repeatCount||5}.`)}if(action==="openMaintenance"){const r=db.maintenanceRequests.find(x=>x.id===el.dataset.maintenance);if(r)return openDrawer(`${r.id} · Maintenance request`,`<div class="notice ${r.status==="completed"?"ok":"info"}"><strong>${esc(maintenanceStatusLabel(r.status))}</strong>${esc(r.description||"Operational maintenance request")}</div><div style="height:14px"></div><div class="metric"><span>Asset</span><strong>${esc(r.asset)}</strong></div><div class="metric"><span>Priority</span>${alarmPriorityTag(r.priority)}</div><div class="metric"><span>Work Order</span><strong class="code">${esc(r.workOrderId||"—")}</strong></div><div class="metric"><span>Source</span><strong class="code">${esc(r.source||"Manual")}</strong></div><div class="metric"><span>Owner</span><strong>${esc(r.owner||"—")}</strong></div>`)}if(action==="advanceMaintenance"){const r=db.maintenanceRequests.find(x=>x.id===el.dataset.maintenance);if(!r)return;r.status=r.status==="open"?"in_progress":"completed";render("maintenance");return notify(`${r.id} updated to ${maintenanceStatusLabel(r.status)}.`)}return alarmAutomationHandle(action,el)};
handle=(action,el)=>{if(action==="newAlarm"){if(typeof createAlertFromForm==="function")return createAlertFromForm()}return alarmAutomationHandle(action,el)};
const renderBaseWithMaintenance=render;render=(next=view)=>{if(next!=="maintenance")return renderBaseWithMaintenance(next);view="maintenance";$("#crumb").textContent="Maintenance requests";$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$("#content").innerHTML=maintenance();bindPage()};
const alarmMaintenanceBind=bindPage;bindPage=()=>{alarmMaintenanceBind();if(view==="alarms"){const filter=()=>{const q=( $("#alarmSearch")?.value||"" ).toLowerCase(),sev=$("#alarmSeverity")?.value||"",state=$("#alarmState")?.value||"",rows=db.alarms.filter(a=>(!q||[a.title,a.source,a.workOrderId,a.errorCode].join(" ").toLowerCase().includes(q))&&(!sev||a.severity===sev)&&(!state||a.status===state));if($("#alarmRowsAdvanced"))$("#alarmRowsAdvanced").innerHTML=alarmRows(rows)||`<tr><td colspan="6"><div class="empty">No alarms match your filters.</div></td></tr>`};["alarmSearch","alarmSeverity","alarmState"].forEach(id=>$("#"+id)?.addEventListener(id==="alarmSearch"?"input":"change",filter))}if(view==="maintenance"){const filter=()=>{const q=( $("#maintenanceSearch")?.value||"" ).toLowerCase(),state=$("#maintenanceStatus")?.value||"",rows=db.maintenanceRequests.filter(r=>(!q||[r.id,r.title,r.asset,r.workOrderId,r.source].join(" ").toLowerCase().includes(q))&&(!state||r.status===state));if($("#maintenanceRows"))$("#maintenanceRows").innerHTML=maintenanceRows(rows)};$("#maintenanceSearch")?.addEventListener("input",filter);$("#maintenanceStatus")?.addEventListener("change",filter)}};
function createAlertFromForm(){openModal("Add alarm + alert automation",`<div class="notice info"><strong>Configure the signal and the response.</strong>The Alarm appears immediately; the Alert counts repeated occurrences and can create a Maintenance Request automatically.</div><div style="height:14px"></div><div class="fields"><div class="field"><label>Severity</label><select id="aaSeverity"><option value="critical">Critical</option><option value="high" selected>High</option><option value="warning">Warning</option><option value="info">Info</option></select></div><div class="field"><label>Machine scope</label><select id="aaSource"><option>All machines</option>${db.machines.map(m=>`<option value="${esc(m.id)}">${esc(m.id)} · ${esc(m.name)}</option>`).join("")}</select></div><div class="field full"><label>Alarm title</label><input id="aaTitle" value="Machine signal outside operating limit"></div><div class="field"><label>Parameter</label><select id="aaParameter"><option>Heartbeat</option><option>Machine status</option><option>Temperature</option><option>Humidity</option><option>Pressure differential</option><option>Camera quality</option><option>Rejected serial rate</option><option>XML result</option></select></div><div class="field"><label>Condition</label><select id="aaOperator"><option value="missing">Missing / offline</option><option value=">">Greater than</option><option value="<">Less than</option><option value="equals">Equals</option><option value="below">Below quality threshold</option></select></div><div class="field"><label>Threshold / value</label><input id="aaThreshold" value="5 minutes"></div><div class="field"><label>Affected Work Order</label><select id="aaWorkOrder">${db.workOrders.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} · Batch ${esc(x.batch)}</option>`).join("")}</select></div><div class="field"><label>Repeat count</label><input id="aaCount" type="number" min="1" value="5"></div><div class="field"><label>Time window</label><select id="aaWindow"><option>10 minutes</option><option selected>30 minutes</option><option>1 hour</option><option>24 hours</option><option>Continuous duration</option></select></div><div class="field"><label>Owner</label><input id="aaOwner" value="Operations"></div><div class="field full"><label>Automatic actions</label><div class="recipe-checks"><label><input type="checkbox" id="aaMaintenance" checked> Create Maintenance Request</label><label><input type="checkbox" id="aaEmail" checked> Send email / notification</label><label><input type="checkbox" id="aaHold"> Put Work Order on Hold</label><label><input type="checkbox" id="aaEscalate"> Escalate to supervisor</label></div></div></div>`,`Save alarm + alert`,()=>{const title=$("#aaTitle").value||"Operational alarm",source=$("#aaSource").value,workOrderId=$("#aaWorkOrder").value,severity=$("#aaSeverity").value,parameter=$("#aaParameter").value,operator=$("#aaOperator").value,threshold=$("#aaThreshold").value||"configured limit",window=$("#aaWindow").value,repeatCount=Number($("#aaCount").value)||1,actions=[$("#aaMaintenance").checked?"maintenance":"",$("#aaEmail").checked?"email":"",$("#aaHold").checked?"hold":"",$("#aaEscalate").checked?"escalate":""].filter(Boolean),a={id:`ALM-${1043+db.alarms.length}`,severity,category:"Machine / IoT",title,source,workOrderId,impact:severity==="critical"?"Work Order automatically placed On hold":"Review before the affected step continues",status:"active_unacknowledged",startedAt:"Just now",errorCode:"USER-CONFIGURED",owner:$("#aaOwner").value||"Operations",parameter,threshold};db.alarms.unshift(a);db.alerts.unshift({id:`ALT-${1000+db.alerts.length+1}`,name:title,source,parameter,operator,threshold,window,severity,actions,occurrences:0,repeatCount,status:"armed",lastTriggered:"Never",owner:a.owner,workOrderId});if(actions.includes("hold")){const affected=db.workOrders.find(x=>x.id===workOrderId);if(affected)affected.status="on_hold"}modalState=null;render("alarms");notify(`${a.id} and its Alert rule were created.`)})}
function editAlertRule(id){const a=db.alerts.find(x=>x.id===id);if(!a)return;openModal("Edit alert rule",`<div class="notice info"><strong>${esc(a.name)}</strong>Update recurrence, window, or automation without changing the source Alarm.</div><div style="height:14px"></div><div class="fields"><div class="field"><label>Repeat count</label><input id="eaCount" type="number" min="1" value="${a.repeatCount||5}"></div><div class="field"><label>Time window</label><select id="eaWindow"><option ${a.window==="10 minutes"?"selected":""}>10 minutes</option><option ${a.window==="30 minutes"?"selected":""}>30 minutes</option><option ${a.window==="1 hour"?"selected":""}>1 hour</option><option ${a.window==="24 hours"?"selected":""}>24 hours</option><option ${a.window==="Continuous duration"?"selected":""}>Continuous duration</option></select></div><div class="field"><label>Rule status</label><select id="eaStatus"><option value="armed" ${a.status==="armed"?"selected":""}>Armed</option><option value="paused" ${a.status==="paused"?"selected":""}>Paused</option></select></div><div class="field full"><label>Automatic actions</label><div class="recipe-checks"><label><input type="checkbox" id="eaMaintenance" ${a.actions?.includes("maintenance")?"checked":""}> Create Maintenance Request</label><label><input type="checkbox" id="eaEmail" ${a.actions?.includes("email")?"checked":""}> Send email</label><label><input type="checkbox" id="eaHold" ${a.actions?.includes("hold")?"checked":""}> Put Work Order on Hold</label></div></div></div>`,`Save changes`,()=>{a.repeatCount=Number($("#eaCount").value)||1;a.window=$("#eaWindow").value;a.status=$("#eaStatus").value;a.actions=[$("#eaMaintenance").checked?"maintenance":"",$("#eaEmail").checked?"email":"",$("#eaHold").checked?"hold":""].filter(Boolean);modalState=null;render("alarms");notify(`${a.id} updated.`)})}
const alarmFinalHandle=handle;handle=(action,el)=>{if(action==="editAlert")return editAlertRule(el.dataset.alert);return alarmFinalHandle(action,el)};
const alarmFinalBind=bindPage;bindPage=()=>{alarmFinalBind();if(view!=="alarms")return;document.querySelectorAll('[data-action="simulateAlert"]').forEach(btn=>{const row=btn.closest(".list-row");if(row&&!row.querySelector('[data-action="editAlert"]')){const edit=document.createElement("button");edit.className="btn small";edit.dataset.action="editAlert";edit.dataset.alert=btn.dataset.alert;edit.textContent="Edit";edit.addEventListener("click",event=>{event.stopPropagation();handle("editAlert",edit)});btn.parentNode.appendChild(edit)}});const table=document.querySelector("#alarmRowsAdvanced")?.closest("table"),head=table?.querySelector("thead tr");if(head&&!Array.from(head.children).some(th=>th.textContent.trim()==="Impact")){const th=document.createElement("th");th.textContent="Impact";head.insertBefore(th,head.children[3]||null)}};
window._alarmTab=window._alarmTab||"live";
function alarmTabButton(id,label){return `<button class="tab ${window._alarmTab===id?"active":""}" data-action="setAlarmTab" data-tab="${id}">${label}</button>`}
function alarmLiveTable(){const list=db.alarms.filter(a=>a.status!=="resolved");return `<div class="filters"><input id="alarmSearch" placeholder="Search alarm, machine, Work Order"><select id="alarmSeverity"><option value="">All severities</option><option>critical</option><option>high</option><option>warning</option><option>info</option></select><select id="alarmState"><option value="">All states</option><option value="active_unacknowledged">Unacknowledged</option><option value="active_acknowledged">Acknowledged</option></select></div><div class="table-wrap"><table><thead><tr><th>Severity</th><th>Alarm</th><th>Source / parameter</th><th>Impact</th><th>Started</th><th>State</th><th>Actions</th></tr></thead><tbody id="alarmRowsAdvanced">${alarmRows(list)}</tbody></table></div>`}
function alarmsUi(){const active=db.alarms.filter(a=>a.status!=="resolved"),openRequests=db.maintenanceRequests.filter(r=>!['completed','cancelled'].includes(r.status));let body="";if(window._alarmTab==="live")body=panel("Live alarms","Alarms received from the backend when a configured condition is met.",alarmLiveTable());else if(window._alarmTab==="rules")body=panel("Alert rules","Rules define when the backend should create an Alarm and which actions should follow.",`<div class="list">${db.alerts.map(a=>`<div class="list-row"><div><strong>${esc(a.name)}</strong><small>${esc(a.source)} · ${esc(a.parameter)} ${esc(a.operator)} ${esc(a.threshold)} · ${esc(a.window)}</small><small>Actions: ${esc((a.actions||[]).join(" · ")||"Notify only")}</small></div><div class="row-actions">${tag(a.status==="armed"?"accepted":"neutral",a.status==="armed"?"Armed":"Paused")}<button class="btn small" data-action="editAlert" data-alert="${esc(a.id)}">Edit rule</button></div></div>`).join("")||`<div class="empty">No alert rules configured.</div>`}</div>`);else body=panel("Alarm history","Resolved alarms remain searchable for audit and investigation.",`<div class="table-wrap"><table><thead><tr><th>Severity</th><th>Alarm</th><th>Source</th><th>Started</th><th>State</th></tr></thead><tbody>${alarmRows(db.alarms.filter(a=>a.status==="resolved"),false)||`<tr><td colspan="5"><div class="empty">No resolved alarms yet.</div></td></tr>`}</tbody></table></div>`);return pageHead("Alarms & incidents","Backend alarms, alert rules, and retained history in one focused workspace.",`<button class="btn" data-view="maintenance">Maintenance requests (${openRequests.length})</button><button class="btn primary" data-action="newAlarm">Add alarm + alert rule</button>`)+`<div class="stats"><div class="stat"><label>Live alarms</label><strong>${active.length}</strong><small>Backend events</small></div><div class="stat"><label>Alert rules</label><strong>${db.alerts.length}</strong><small>Configured rules</small></div><div class="stat"><label>Open maintenance</label><strong>${openRequests.length}</strong><small>Linked requests</small></div></div><div class="panel"><div class="panel-head"><div><h2>Alarm workspace</h2><p>Save a rule first; a Live Alarm appears only after a matching backend event.</p></div></div><div class="panel-body"><div class="tabs alarm-tabs">${alarmTabButton("live","Live alarms")}${alarmTabButton("rules","Alert rules")}${alarmTabButton("history","History")}</div>${body}</div></div>`}
alarmsEnhanced=alarmsUi;alarms=alarmsUi;
const alarmUiHandle=handle;handle=(action,el)=>{if(action==="setAlarmTab"){window._alarmTab=el.dataset.tab;return render("alarms")}return alarmUiHandle(action,el)};
const alarmUiBind=bindPage;bindPage=()=>{alarmUiBind();if(view!=="alarms")return;const filter=()=>{const q=( $("#alarmSearch")?.value||"" ).toLowerCase(),sev=$("#alarmSeverity")?.value||"",state=$("#alarmState")?.value||"",rows=db.alarms.filter(a=>a.status!=="resolved"&&(!q||[a.title,a.source,a.workOrderId,a.errorCode,a.parameter].join(" ").toLowerCase().includes(q))&&(!sev||a.severity===sev)&&(!state||a.status===state));if($("#alarmRowsAdvanced"))$("#alarmRowsAdvanced").innerHTML=alarmRows(rows)||`<tr><td colspan="7"><div class="empty">No live alarms match your filters.</div></td></tr>`};["alarmSearch","alarmSeverity","alarmState"].forEach(id=>$("#"+id)?.addEventListener(id==="alarmSearch"?"input":"change",filter))};
function maintenanceUi(){const open=db.maintenanceRequests.filter(r=>!['completed','cancelled'].includes(r.status));return pageHead("Maintenance requests","Repair tickets created manually or automatically from Alert rules.",`<button class="btn" data-view="alarms">Back to alarms</button><button class="btn primary" data-action="newMaintenance">Create request</button>`)+`<div class="stats"><div class="stat"><label>Open</label><strong>${open.length}</strong><small>Needs action</small></div><div class="stat"><label>In progress</label><strong>${open.filter(r=>r.status==="in_progress").length}</strong><small>Assigned work</small></div><div class="stat"><label>Auto-created</label><strong>${db.maintenanceRequests.filter(r=>String(r.source||"").startsWith("ALT-")).length}</strong><small>From Alerts</small></div><div class="stat"><label>Completed</label><strong>${db.maintenanceRequests.filter(r=>r.status==="completed").length}</strong><small>Audit retained</small></div></div><div class="panel"><div class="panel-head"><div><h2>Maintenance register</h2><p>Use Details to inspect the ticket, Start to assign it, and Complete to close it.</p></div><span class="tag info">${db.maintenanceRequests.length} requests</span></div><div class="panel-body"><div class="filters"><input id="maintenanceSearch" placeholder="Search request, machine, Work Order"><select id="maintenanceStatus"><option value="">All statuses</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select></div><div class="table-wrap"><table><thead><tr><th>Request</th><th>Asset / source</th><th>Priority</th><th>Work Order</th><th>Created</th><th>Status</th><th>Actions</th></tr></thead><tbody id="maintenanceRows">${maintenanceRows(db.maintenanceRequests)}</tbody></table></div></div></div>`}
